import {createSync} from './sync.js?v=21f3358aa63b';
import {id,today,addDays,days,monthDate,day,money,emptyState,validateState,calculate,budgets,budgetPeriod,payroll,shiftPay,cancelTransaction,cancelGeneratedEvent,resolvePayment,debtRemaining,settleDebt,debtInterest,debtAvailable,recordDebtActivity} from './core.js?v=21f3358aa63b';
const testing=new URLSearchParams(location.search).has('test');
const KEY='kurashi-budget-v1'+(testing?'-test':''),BACKUP=KEY+'-previous';
let state=emptyState(),loadError='',tab='home',section='',filter='all',group='all',view='list',selectedDate='',calendarMonth=today().slice(0,7)+'-01',result,setupStep=0;
try{const saved=localStorage.getItem(KEY);if(saved)state=validateState(JSON.parse(saved));}catch(e){loadError='保存データを読み込めませんでした。元のデータは上書きせず保護しています。バックアップから復元してください。';}
const $=s=>document.querySelector(s),esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
