const paymentOptions=()=>[...accountOptions().map(([v,l])=>['a:'+v,l]),...state.cards.map(c=>['c:'+c.id,c.name+'（クレジット）']),...state.debitCards.map(c=>['d:'+c.id,c.name+'（デビット）'])];
